result=js(r'''(async()=>{const T=await import('three'),{createTrees}=await import('./js/world/trees.js');const check=(v,m)=>{if(!v)throw Error(m)},placements=Array.from({length:12},(_,i)=>({x:i*6,z:-15,h:3,crown:2.4,base:.1})),g=await createTrees(placements),trees=g.getObjectByName('trees-billboards'),shrubs=g.getObjectByName('tree-understory');check(shrubs?.isInstancedMesh,'one cheap understory batch');check(g.children.length===2&&trees.count===12,'bounded vegetation batches');check(trees.instanceColor&&new Set(Array.from(trees.instanceColor.array).map(v=>v.toFixed(3))).size>4,'deterministic foliage tints');const m=new T.Matrix4(),p=new T.Vector3(),q=new T.Quaternion(),s=new T.Vector3();for(let i=0;i<shrubs.count;i++){shrubs.getMatrixAt(i,m);m.decompose(p,q,s);const original=placements[shrubs.userData.sourceIndices[i]];check(Math.hypot(p.x-original.x,p.z-original.z)+Math.max(s.x,s.z)<=original.crown/2+.001,'understory inside existing canopy footprint');check(p.y-s.y>=0&&p.y+s.y<1,'low shrubs keep views open');}check(typeof g.userData.dispose==='function','vegetation owns teardown');let disposed=0;g.children.forEach(m=>m.geometry.addEventListener('dispose',()=>disposed++));g.userData.dispose();g.userData.dispose();check(disposed===2,'vegetation disposes its geometry once');return {pass:true,trees:trees.count,shrubs:shrubs.count,batches:g.children.length};})()''')
